<span class="line"><span style="color:#E1E4E8;">    city </span><span style="color:#B392F0;">VARCHAR</span><span style="color:#E1E4E8;">(</span><span style="color:#79B8FF;">50</span><span style="color:#E1E4E8;">),</span></span>
