<span class="line"><span style="color:#E1E4E8;">    FOREIGN </span><span style="color:#B392F0;">KEY</span><span style="color:#E1E4E8;"> (user_id) REFERENCES </span><span style="color:#B392F0;">users</span><span style="color:#E1E4E8;">(id)</span></span>
