<span class="line"><span style="color:#9ECBFF;">  &quot;_id&quot;</span><span style="color:#F97583;">:</span><span style="color:#B392F0;"> ObjectId</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;60f7a4b3e9a2c34567890123&quot;</span><span style="color:#E1E4E8;">),</span></span>
